// AWI: diagnosa TiTAN brosur sementara (hapus setelah dipakai)
add_action('rest_api_init', function () {
	register_rest_route('awi/v1', '/tdiag', array(
		'methods' => 'GET',
		'permission_callback' => function () { return current_user_can('manage_options'); },
		'callback' => function ($req) {
			global $wpdb;
			$w = $req->get_param('w');
			$out = array();
			if ($w === 'model') {
				$c = get_post_field('post_content', 10706);
				$a = strpos($c, 'Pilihan Warna'); $s = strrpos(substr($c, 0, $a), '<h2');
				$e = strpos($c, '<h2', $a + 20);
				$out['warna'] = array($s, $e, substr($c, max(0, $s - 400), min(5200, $e - $s + 400)));
				$a2 = strpos($c, 'Spesifikasi Lengkap'); $s2 = strrpos(substr($c, 0, $a2), '<h2'); $e2 = strpos($c, '<h2', $a2 + 20);
				$out['spec'] = array($s2, $e2, substr($c, $s2, 900), substr($c, $e2 - 600, 650));
			} else {
				$terms = array('160 kW', '260 N', '179 hp', '133 kW', 'Jade Green', 'Mountain Green', 'Titanium Grey', 'Starlight Silver', 'Obsidian Black', 'byd-ti7-', 'Massage', 'massage', 'pijat', '6 arah', '8 arah', '12 arah');
				$rows = $wpdb->get_results("SELECT ID, post_type, post_content FROM {$wpdb->posts} WHERE post_status='publish' AND post_type IN ('page','post','model')");
				foreach ($rows as $r) foreach ($terms as $t) { $i = 0; $k = 0; while (($i = strpos($r->post_content, $t, $i)) !== false && $k < 6) { $out[$r->ID][] = $t . ' | ' . preg_replace('/\s+/', ' ', wp_strip_all_tags(substr($r->post_content, max(0, $i - 120), 260))); $i += strlen($t); $k++; } }
				$sn = $wpdb->get_results("SELECT id, code FROM {$wpdb->prefix}snippets WHERE active=1");
				foreach ($sn as $r) foreach ($terms as $t) { if (strpos($r->code, $t) !== false) $out['snip' . $r->id][] = $t . ' | ' . substr($r->code, max(0, strpos($r->code, $t) - 100), 220); }
				foreach (array(10696,10697,10698,10699,10700,10701,10702,10703,10704,10705) as $id) $out['att'][$id] = wp_get_attachment_url($id);
			}
			return $out;
		},
	));
});
